    intro: [
      '《魏書》〈太祖紀〉記北魏道武帝拓跋珪的事。教育部辭典說拓跋氏在晉朝時自立為代王,後來改國號為魏,歷史上稱為「後魏」或「北魏」。天興元年,他讓大臣討論國號:',
      { orig: '六月丙子，詔有司議定國號。羣臣曰：「昔周秦以前，世居所生之土，有國有家，及王天下，即承為號。自漢以來，罷侯置守，時無世繼，其應運而起者，皆不由尺土之資。今國家萬世相承，啟基雲代。臣等以為若取長遠，應以代為號。」', tr: '六月丙子日,他下詔要官員討論決定國號。大臣們說:「從前周朝、秦朝以前,君主世代住在出生的土地上,有自己的封國和家族,等到統治天下,就沿用原來的名稱當國號。漢朝以後,不再分封諸侯,改派郡守,君主沒有世代相傳的封地,那些順著時運興起的人,都不是靠一小塊封地起家的。現在我們國家世代相傳,是在雲中、代地打下基業的。我們認為,要取長久的意思,應該用『代』當國號。」' },
      { orig: '詔曰：「昔朕遠祖，總御幽都，控制遐國，雖踐王位，未定九州。逮于朕躬，處百代之季，天下分裂，諸華乏主。……宜仍先號，以為魏焉。布告天下，咸知朕意。」', tr: '他下詔說:「從前我的遠祖統治北方,控制遙遠的地方,雖然登上王位,卻還沒有平定天下。到了我這一代,正逢許多朝代之後,天下分裂,中原各國沒有共同的君主。……應該沿用先前的稱號,叫做『魏』。公告天下,讓大家都知道我的意思。」' },
      '可以和金朝「大金」、元朝「大元」、清朝「大清」國號那幾張卡對照。',
      { gloss: [['詔', '皇帝下命令。'], ['有司', '負責的官員。'], ['罷侯置守', '不再分封諸侯,改派郡守治理。'], ['尺土之資', '一小塊土地的憑藉。'], ['啟基', '打下基業。'], ['雲代', '雲中和代地(地名)。'], ['幽都', '北方。'], ['遐', '遙遠。'], ['踐', '登上。'], ['季', '末尾。'], ['諸華', '中原各國。']] },
    ],
